#!/bin/bash
#SBATCH --job-name=overlap_combine_ET
#SBATCH --output=logs/dingo/%x_%j.out
#SBATCH --error=logs/dingo/%x_%j.err
#SBATCH --ntasks=1
#SBATCH --cpus-per-task=16
#SBATCH --partition=private-dpnc-gpu
#SBATCH --time=24:00:00
#SBATCH --mem=128G

# Combine two 5M ET datasets into waveform_dataset_ET_joint_5M.hdf5.
#
#   1. combine signal 1 with signal 2 shifted earlier by U(0.01, 0.5) s
#   2. verify the result loads as a dingo WaveformDataset
#   3. delete the temporary second dataset
#
# Signal 2 is generated by a SEPARATE job:
#
#   GEN=$(sbatch --parsable generate_waveform_ET.sh training_data/waveform_dataset_ET_5M_tmp.hdf5)
#   sbatch --dependency=afterok:$GEN overlap_combine_submission.sh
#
# afterok, not afterany: generate_waveform_ET.sh ends with an assert that the new
# dataset has geocent_time == 0, so a bad dataset exits non-zero and this job never
# starts. waveform_dataset_ET_5M.hdf5 is only ever read, never modified.
#
# Pure BLAS -- no --gres, so this takes CPUs on a GPU node without holding a card.
# private-dpnc-cpu looks like the natural home but is chronically saturated: its
# 13 nodes leave only 2-8 idle cores each (4 down, 1 drained), so a 16-core request
# sits at Reason=Priority with StartTime=Unknown indefinitely. private-dpnc-gpu had
# 735 idle cores at the same moment. Peak memory is ~40 GB in the SVD basis build;
# 128G fits every node of both partitions.

set -eo pipefail

SIGNAL1=${SIGNAL1:-training_data/waveform_dataset_ET_5M.hdf5}
SIGNAL2=${SIGNAL2:-training_data/waveform_dataset_ET_5M_tmp.hdf5}   # deleted at the end
JOINT=${JOINT:-training_data/waveform_dataset_ET_joint_5M.hdf5}

SHIFT_MIN=${SHIFT_MIN:-0.01}
SHIFT_MAX=${SHIFT_MAX:-0.5}
SVD_SIZE=${SVD_SIZE:-600}

mkdir -p logs/dingo
echo "HOSTNAME=$(hostname)"
echo "PWD=$(pwd)"
echo "SIGNAL1=$SIGNAL1 (kept)"
echo "SIGNAL2=$SIGNAL2 (deleted after a successful combine)"
echo "JOINT=$JOINT"
echo "shift U($SHIFT_MIN, $SHIFT_MAX) s, SVD size $SVD_SIZE"

export PYTHONUNBUFFERED=1
export OMP_NUM_THREADS=${SLURM_CPUS_PER_TASK:-16}

module load GCCcore/12.3.0
module load Python/3.11.3
source $HOME/venvs/dingo_env/bin/activate
export PYTHONPATH=/srv/beegfs/dpnc/groups/gw/Peng/projects/dingo:$HOME/.local/lib/python3.11/site-packages

for f in "$SIGNAL1" "$SIGNAL2"; do
    if [ ! -f "$f" ]; then
        echo "ERROR: $f does not exist." >&2
        exit 1
    fi
done

# --- 1. combine ---------------------------------------------------------------
echo; echo "=== 1/3 combining into $JOINT ==="
python make_overlapping_dataset.py \
    --signal1 "$SIGNAL1" \
    --signal2 "$SIGNAL2" \
    --out "$JOINT" \
    --shift-min "$SHIFT_MIN" \
    --shift-max "$SHIFT_MAX" \
    --svd-size "$SVD_SIZE" \
    --check-wrap

# --- 2. verify ----------------------------------------------------------------
# Only delete the temporary dataset once the joint one is known to be readable.
echo; echo "=== 2/3 verifying $JOINT ==="
python -c "
from dingo.gw.dataset import WaveformDataset
import numpy as np
wfd = WaveformDataset(file_name='$JOINT', precision='single')
print('samples:      ', len(wfd.parameters))
print('columns:      ', list(wfd.parameters.columns))
print('delta_tc_2:    %.4f .. %.4f s' % (wfd.parameters['delta_tc_2'].min(),
                                          wfd.parameters['delta_tc_2'].max()))
print('geocent_time:  ', np.unique(wfd.parameters['geocent_time']))
sample = wfd[0]
print('decompressed:  ', {k: v.shape for k, v in sample['waveform'].items()})
assert np.allclose(wfd.parameters['geocent_time'], 0.0), 'signal 1 must sit at t=0'
assert np.isfinite(sample['waveform']['h_plus']).all()
print('OK')
"

# --- 3. clean up --------------------------------------------------------------
echo; echo "=== 3/3 removing temporary $SIGNAL2 ==="
rm -f "$SIGNAL2"
ls -lh training_data/*.hdf5

echo "Done."
